#!/bin/bash
# Removes every output directory/file generated by steps 1-14 of
# run_pipeline_for_final_fits_tth_th.sh, so a fresh run starts from a clean
# state. Re-run the earlier steps afterward to regenerate everything this
# removes.
#
# Deliberately NOT touched:
#   - the raw HiggsDNA ntuples under ${RAW_BASE}/root/ (only the ws_*
#     subfolders step 1/2 create inside them are removed, never the ntuples
#     or their parent sample directories)
#   - the external eos copy from step 12 (run_move_file_to_eos.sh's
#     date-stamped DEST_BASE under /eos/home-m/mikumar/php-plots/...) - that
#     lives outside this repo and may be referenced elsewhere; clean it up
#     manually if you ever need to.

if [[ "$1" == "-h" ]] || [[ "$1" == "--help" ]]; then
    echo "Usage: $0"
    echo
    echo "  Deletes all generated output from steps 1-14 (see the comment at"
    echo "  the top of this file for the exact list). Raw ntuples and the"
    echo "  step-12 eos copy are left untouched."
    echo "  -h, --help   Show this help message"
    exit 0
fi

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
RAW_BASE="/eos/user/m/mikumar/Final_fits/outputForFinalFits_29Oct2026"

echo "===== RESET: removing pipeline-generated output ====="

# Step 1 (Trees2WS MC): ws_* subfolders inside root/<sample>_<year>/.
# Scoped to exactly "ws_*" dirs one level inside root/ - never removes the
# raw .root ntuples or their parent sample directories.
echo " --> [1] root/*/ws_* subfolders"
find "${RAW_BASE}/root" -mindepth 2 -maxdepth 2 -type d -name "ws_*" -exec rm -rf {} +

# Step 2 (Trees2WS data): root/Data/ws/
echo " --> [2] root/Data/ws/"
rm -rf "${RAW_BASE}/root/Data/ws"

# Step 3 (club_workspaces): the whole flattened workspaces/ tree - pure
# derived output, safe to remove wholesale.
echo " --> [3] workspaces/"
rm -rf "${RAW_BASE}/workspaces"

# Step 4 (Signal fit): signalFit output + packaged workspaces/plots
echo " --> [4] Signal/outdir_tth_th_cp_Analysis/, Signal/outdir_packaged/"
rm -rf "${SCRIPT_DIR}/Signal/outdir_tth_th_cp_Analysis"
rm -rf "${SCRIPT_DIR}/Signal/outdir_packaged"

# Step 5 (Plot background): pre-fit background shape plots
echo " --> [5] Background/plots_background/"
rm -rf "${SCRIPT_DIR}/Background/plots_background"

# Step 6 (Background fit): multipdf fits + multipdf plots
echo " --> [6] Background/outdir_tth_th_cp_Analysis/, Background/plots_tth_th_cp_Analysis*/"
rm -rf "${SCRIPT_DIR}/Background/outdir_tth_th_cp_Analysis"
rm -rf "${SCRIPT_DIR}/Background"/plots_tth_th_cp_Analysis*

# Steps 7+9 (Create yields / Event counts): same directory - yields pkls
# plus the per-category *_numEvents.txt files step 9 adds alongside them.
echo " --> [7,9] Datacard/yields_tth_th_cp_Analysis/"
rm -rf "${SCRIPT_DIR}/Datacard/yields_tth_th_cp_Analysis"

# Steps 8+10 (Yields table / Event counts table): same output directory
echo " --> [8,10] Plots/Tables/"
rm -rf "${SCRIPT_DIR}/Plots/Tables"

# Step 11 (Build datacard): the datacard text + saved dataframe
echo " --> [11] Datacard/Datacard_tth_th_cp_Analysis.txt, .pkl"
rm -f "${SCRIPT_DIR}/Datacard/Datacard_tth_th_cp_Analysis.txt"
rm -f "${SCRIPT_DIR}/Datacard/Datacard_tth_th_cp_Analysis.pkl"

# Step 12 (Move to eos): intentionally NOT removed - see header comment.

# Step 13 (Plot signal shape): diagnostic plot output
echo " --> [13] Datacard/outputs/"
rm -rf "${SCRIPT_DIR}/Datacard/outputs"

# Step 14 (Combine): text2workspace job dir + combine/text2workspace output
echo " --> [14] Combine/t2w_jobs/, Combine/*_cpTopHiggs.root, Combine/higgsCombine*.root, Combine/scan1d_fcp.pdf"
rm -rf "${SCRIPT_DIR}/Combine/t2w_jobs"
rm -f "${SCRIPT_DIR}/Combine"/*_cpTopHiggs.root
rm -f "${SCRIPT_DIR}/Combine"/higgsCombine*.root
rm -f "${SCRIPT_DIR}/Combine/scan1d_fcp.pdf"

echo "===== RESET COMPLETE ====="
